  "about_items": [
    {
      "n": "#117·09",
      "text": "The graphite skirt features a straight, knee-length cut with an asymmetrical front opening secured by three polished silver buttons. Its tailored silhouette is defined by two structured flap pockets at the hips, crafted from the same heavy fabric that gives the piece a substantial, luxurious feel."
    },
    {
      "n": "#83·33",
      "text": "The grey blazer showcases a fine vertical pinstripe pattern set against a dark charcoal background. It has a fitted silhouette with a sharp notched lapel, a single button closure, and distinctive peplum detailing at the hem that gently flares over the hips."
    },
    {
      "n": "#26·17",
      "text": "The burgundy boots are crafted from soft, slouchy suede that gathers elegantly around the calf. They feature a sturdy black block heel and a rounded toe, offering both stability and height in a rich, deep color."
    },
    {
      "n": "#429·21",
      "text": "The terracotta coat is designed with a relaxed wrap silhouette, featuring voluminous sleeves that gather at the wrist. It is distinguished by its contrasting black velvet lapels and a matching wide velvet belt that cinches at the waist, creating a sophisticated hourglass shape."
    },
    {
      "n": "#495·38",
      "text": "The chocolate scarf is made from a soft, double-sided fabric with a subtle color variation between its two faces. It finishes with delicate fringes along both edges, adding a touch of movement and texture to the ensemble."
    },
    {
      "n": "#181·03",
      "text": "The ginger tote is structured in smooth, grained leather with long top handles attached by metal buckles for adjustability. It features minimal detailing, with a small metallic logo on the front and visible stitching that highlights its clean lines."
    }
  ]
}
